import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"物镜像差测量","description":"","frontmatter":{"title":"物镜像差测量","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lens-aberration-metrology.md","filePath":"litho/lens-aberration-metrology.md","lastUpdated":1789023840000}'),E={name:"litho/lens-aberration-metrology.md"};function c(_,a,m,A,u,B){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="物镜像差测量" tabindex="-1">物镜像差测量 <a class="header-anchor" href="#物镜像差测量" aria-label="Permalink to &quot;物镜像差测量&quot;">​</a></h1><div class="epigraph"><p>操纵器没有眼睛。相位测量、剪切干涉或晶圆上像差探针，才把 Zernike 从故事变成伏特。</p><footer>—— 对照光学车间检测（Malacara）与扫描仪内像差计量；[Zernike](/litho/zernike-aberrations)</footer></div><p><a href="/litho/fused-silica-caf2">上一课</a>给出玻璃。缺口是计量：如何在机台上看到波前。本课钉物镜像差测量，执行器映射已在操纵器课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离线干涉仪看冷态镜头；装进扫描仪后，热、气压、浸没水都会改数。只用出厂报告，补偿表是开环。晶圆上 CD 是混叠了胶、聚焦、照明的结果，不能当纯 Zernike 传感器。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>层次：出厂全口径干涉；机内源/光瞳相关的波前传感器；专用像差标记 + 散射或成像重建缝内低阶项。报告要声明：干式还是浸没、哪一缝位置、哪一波长。与 <a href="/litho/pupil-metrology">光瞳测量</a> 分工：那边是照明角谱，这边是投影相位。</p>',7)),(e(),s(p,null,{default:r(()=>[h(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20IF%5B%22%E5%87%BA%E5%8E%82%E5%B9%B2%E6%B6%89%22%5D%20--%3E%20BASE%5B%22%E5%86%B7%E6%80%81%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20IN%5B%22%E6%9C%BA%E5%86%85%E6%B3%A2%E5%89%8D%E8%AE%A1%22%5D%20--%3E%20RUN%5B%22%E8%BF%90%E8%A1%8C%E6%80%81%20Zernike%22%5D%0A%20%20WAF%5B%22%E6%99%B6%E5%9C%86%E6%8E%A2%E9%92%88%22%5D%20--%3E%20RUN%0A%20%20RUN%20--%3E%20MAN%5B%22%E6%93%8D%E7%BA%B5%E5%99%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">浸没下末片–水界面是计量的一部分。把水拿掉测，再声称浸没像差，会差一层折射率与面形负载。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>干涉把相位变成条纹；Zernike 拟合把条纹变成系数向量。噪声和遮拦使高阶项方差大，故反馈只用信噪比够的低阶。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课双折射：即使相位 Zernike 完美，偏振像差仍能毁对比。标量相位计量不够。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>像差计量必须在运行态（含浸没）闭合。</li><li>与照明光瞳计分开；CD 不是纯波前计。</li><li>出处：Optical Shop Testing；Zernike 课。</li></ul>',7))])}const k=i(E,[["render",c]]);export{b as __pageData,k as default};
